def _optimization_tool_definitions(config) -> dict[str, dict[str, Any]]:
    if config is None:
        return {}

    definitions: dict[str, dict[str, Any]] = {}
    for definition in config.tool_definitions or []:
        function = definition.get("function") if isinstance(definition, dict) else None
        if not isinstance(function, dict):
            continue
        name = function.get("name")
        if not isinstance(name, str) or not name:
            continue
        definitions[name] = function
        definitions[_sanitize_tool_name(name)] = function
    return definitions


def _apply_optimized_tool_schema(
    mcp_name: str,
    description: str,
    schema: dict[str, Any],
    optimized_tools: dict[str, dict[str, Any]],
) -> tuple[str, dict[str, Any]]:
    function = optimized_tools.get(mcp_name) or optimized_tools.get(_sanitize_tool_name(mcp_name))
    if not function:
        return description, schema

    optimized_description = function.get("description")
    if isinstance(optimized_description, str) and optimized_description.strip():
        description = optimized_description.strip()

    optimized_parameters = function.get("parameters")
    if not isinstance(optimized_parameters, dict):
        return description, schema

    patched_schema = copy.deepcopy(schema)
    properties = patched_schema.get("properties")
    optimized_properties = optimized_parameters.get("properties")
    if isinstance(properties, dict) and isinstance(optimized_properties, dict):
        for parameter_name, optimized_property in optimized_properties.items():
            property_schema = properties.get(parameter_name)
            if not isinstance(property_schema, dict) or not isinstance(optimized_property, dict):
                continue
            parameter_description = optimized_property.get("description")
            if isinstance(parameter_description, str) and parameter_description.strip():
                property_schema["description"] = parameter_description.strip()

    return description, patched_schema


def _session_already_exists_error(exc: Exception) -> bool:
    """Detect create_session conflicts across SDK versions."""
    message = str(exc).lower()
    return "already exists" in message or "already_exist" in message


def _strip_project_path(endpoint: str) -> str:
    """Return just the AI Services base URL, stripping any /api/projects/... suffix.

    FOUNDRY_PROJECT_ENDPOINT is injected as:
      https://<account>.services.ai.azure.com/api/projects/<project>
    The CopilotClient Azure provider needs only:
      https://<account>.services.ai.azure.com
    and appends /openai/deployments/<model> itself.
    """
    normalized = endpoint.rstrip("/")
    idx = normalized.find("/api/projects")
    return normalized[:idx] if idx > 0 else normalized


