def _sanitize_tool_name(name: str) -> str:
    return name.replace(".", "_").replace("-", "_")


class McpBridge:
    """HTTP bridge for calling a Foundry toolbox MCP endpoint."""

    def __init__(self, endpoint: str, token: str):
        self.endpoint = endpoint
        self.headers = _get_toolbox_headers(token)
        self._session_id: str | None = None
        self._client = httpx.AsyncClient(timeout=60.0)
        self._req_id = 0

    def _next_id(self) -> int:
        self._req_id += 1
        return self._req_id

    def _request_headers(self) -> dict[str, str]:
        headers = dict(self.headers)
        if self._session_id:
            headers["mcp-session-id"] = self._session_id
        if call_id := agent_memory.request_identity()[1]:
            headers[agent_memory.FOUNDRY_CALL_HEADER] = call_id
        return headers

    async def initialize(self) -> str:
        response = await self._client.post(
            self.endpoint,
            headers=self.headers,
            json={
                "jsonrpc": "2.0",
                "id": self._next_id(),
                "method": "initialize",
                "params": {
                    "protocolVersion": "2025-03-26",
                    "capabilities": {},
                    "clientInfo": {
                        "name": "copilot-toolbox-bridge",
                        "version": "1.0.0",
                    },
                },
            },
        )
        response.raise_for_status()
        data = response.json()
        self._session_id = response.headers.get("mcp-session-id")

        await self._client.post(
            self.endpoint,
            headers=self._request_headers(),
            json={"jsonrpc": "2.0", "method": "notifications/initialized"},
        )
        return data.get("result", {}).get("serverInfo", {}).get("name", "unknown")

    async def list_tools(self) -> list[dict[str, Any]]:
        response = await self._client.post(
            self.endpoint,
            headers=self._request_headers(),
            json={
                "jsonrpc": "2.0",
                "id": self._next_id(),
                "method": "tools/list",
                "params": {},
            },
        )
        response.raise_for_status()
        payload = response.json()
        if isinstance(payload.get("error"), dict):
            logger.warning("toolbox tools/list error: %s", payload["error"].get("message"))
            return []
        return payload.get("result", {}).get("tools", [])

    async def list_resources(self) -> list[dict[str, Any]]:
        response = await self._client.post(
            self.endpoint,
            headers=self._request_headers(),
            json={
                "jsonrpc": "2.0",
                "id": self._next_id(),
                "method": "resources/list",
                "params": {},
            },
        )
        response.raise_for_status()
        payload = response.json()
        return payload.get("result", {}).get("resources", [])

    async def read_resource(self, uri: str) -> str | None:
        response = await self._client.post(
            self.endpoint,
            headers=self._request_headers(),
            json={
                "jsonrpc": "2.0",
                "id": self._next_id(),
                "method": "resources/read",
                "params": {"uri": uri},
            },
        )
        response.raise_for_status()
        payload = response.json()
        contents = payload.get("result", {}).get("contents", [])
        for item in contents:
            if isinstance(item, dict) and isinstance(item.get("text"), str):
                return item["text"]
        return None

    async def call_tool(self, name: str, arguments: dict[str, Any]) -> str:
        response = await self._client.post(
            self.endpoint,
            headers=self._request_headers(),
            json={
                "jsonrpc": "2.0",
                "id": self._next_id(),
                "method": "tools/call",
                "params": {"name": name, "arguments": arguments},
            },
        )
        response.raise_for_status()
        result = response.json().get("result", {})
        content = result.get("content", [])
        texts = [
            item.get("text", "")
            for item in content
            if isinstance(item, dict) and item.get("type") == "text"
        ]
        return "\n".join(text for text in texts if text) or json.dumps(result)

    async def close(self) -> None:
        await self._client.aclose()


def _make_copilot_tools(
    bridge: McpBridge,
    mcp_tools: list[dict[str, Any]],
    optimized_tools: dict[str, dict[str, Any]] | None = None,
) -> list[Tool]:
    tools: list[Tool] = []
    optimized_tools = optimized_tools or {}
    for mcp_tool in mcp_tools:
        mcp_name = mcp_tool.get("name")
        if not isinstance(mcp_name, str) or not mcp_name:
            continue

        schema = mcp_tool.get("inputSchema")
        if not isinstance(schema, dict):
            schema = {"type": "object", "properties": {}}

        description = mcp_tool.get("description")
        if not isinstance(description, str) or not description.strip():
            description = f"MCP tool: {mcp_name}"
        description, schema = _apply_optimized_tool_schema(
            mcp_name, description, schema, optimized_tools
        )

        async def _handler(invocation: ToolInvocation, original_name: str = mcp_name) -> ToolResult:
            arguments = invocation.arguments if isinstance(invocation.arguments, dict) else {}
            try:
                result_text = await bridge.call_tool(original_name, arguments)
                return ToolResult(text_result_for_llm=result_text)
            except Exception as exc:
                return ToolResult(
                    text_result_for_llm="",
                    result_type="error",
                    error=str(exc),
                )

        tools.append(
            Tool(
                name=_sanitize_tool_name(mcp_name),
                description=description,
                parameters=schema,
                handler=_handler,
                skip_permission=True,
            )
        )
    return tools


def _skill_name_for_tool(tool_name: str) -> str:
    return tool_name.replace("_", "-")


def _make_skill_backed_tools(
    optimized_tools: dict[str, dict[str, Any]],
    skills_root: str,
    existing_names: set[str],
) -> list[Tool]:
    """Expose configured function tools backed by toolbox skill resources.

    The toolbox MCP endpoint serves the Public library assistant guidance as skill resources, not
    callable MCP tools. Registering the configured function schema keeps tool
    routing observable and evaluable while the answer stays grounded in the
    toolbox-published guidance.
    """
    tools: list[Tool] = []
    root = pathlib.Path(skills_root)
    for name, function in optimized_tools.items():
        if name != function.get("name") or _sanitize_tool_name(name) in existing_names:
            continue
        skill_file = root / _skill_name_for_tool(name) / "SKILL.md"
        if not skill_file.is_file():
            continue
        parameters = function.get("parameters")
        if not isinstance(parameters, dict):
            parameters = {"type": "object", "properties": {}}

        async def _handler(
            invocation: ToolInvocation, path: pathlib.Path = skill_file, skill: str = _skill_name_for_tool(name)
        ) -> ToolResult:
            guidance = path.read_text(encoding="utf-8")
            return ToolResult(text_result_for_llm=f"Public library assistant toolbox guidance ({skill}):\n{guidance}")

        tools.append(
            Tool(
                name=_sanitize_tool_name(name),
                description=str(function.get("description") or f"Toolbox skill: {name}"),
                parameters=parameters,
                handler=_handler,
                skip_permission=True,
            )
        )
    return tools


def _skill_resource_to_path(uri: str) -> tuple[str, str] | None:
    if not uri.startswith("skill://"):
        return None

    suffix = uri[len("skill://"):]
    if not suffix or "/" not in suffix:
        return None

    skill_name, relative_path = suffix.split("/", 1)
    if not skill_name or not relative_path:
        return None

    return skill_name, relative_path


async def _sync_toolbox_skills(bridge: McpBridge, target_root: str) -> int:
    root = pathlib.Path(target_root)
    root.mkdir(parents=True, exist_ok=True)

    resources = await bridge.list_resources()
    synced = 0
    for resource in resources:
        if not isinstance(resource, dict):
            continue
        uri = resource.get("uri")
        if not isinstance(uri, str):
            continue

        skill_path = _skill_resource_to_path(uri)
        if skill_path is None:
            continue

        text = await bridge.read_resource(uri)
        if not text:
            continue
        text = _normalize_skill_text(text)

        skill_name, relative_path = skill_path
        destination = root / skill_name / relative_path
        destination.parent.mkdir(parents=True, exist_ok=True)
        destination.write_text(text, encoding="utf-8")
        synced += 1

    return synced


def _normalize_skill_text(text: str) -> str:
    """Normalize skill markdown returned by toolbox resources/read.

    Some toolbox skill payloads contain two consecutive frontmatter blocks. The
    Copilot skill loader expects a single frontmatter block.
    """
    if not text.startswith("---\n"):
        return text

    first_end = text.find("\n---\n", 4)
    if first_end < 0:
        return text

    remainder = text[first_end + 5 :].lstrip("\n")
    if remainder.startswith("---\n"):
        return remainder
    return text


# ── BYOK helpers ─────────────────────────────────────────────────────────────


def _is_unresolved_template(value: str) -> bool:
    """Return True when a value still looks like an unexpanded template."""
    text = value.strip()
    return text.startswith("${") and text.endswith("}")


def _resolve_model_deployment_name(model_override: str | None = None) -> str | None:
    """Resolve model deployment name from known env vars.

    Some deploy flows can leave `AZURE_AI_MODEL_DEPLOYMENT_NAME` as a literal
    `${...}` string when the template value was not provided. In that case, fall
    back to other common variable names if present.
    """
    if model_override and not _is_unresolved_template(model_override):
        return model_override

    candidates = (
        "AZURE_AI_MODEL_DEPLOYMENT_NAME",
        "MODEL_DEPLOYMENT_NAME",
        "FOUNDRY_MODEL_DEPLOYMENT",
        "FOUNDRY_MODEL_DEPLOYMENT_NAME",
    )

    for key in candidates:
        value = (os.environ.get(key) or "").strip()
        if not value or _is_unresolved_template(value):
            continue
        return value
    return None


def _byok_provider(model_override: str | None = None) -> tuple[ProviderConfig | None, str | None]:
    """Return (provider, model) for BYOK mode when a Foundry model is configured.

    FOUNDRY_PROJECT_ENDPOINT (injected by the platform) is stripped to just the
    AI Services host. The SDK appends /openai/deployments/<model> automatically.
    Uses cognitiveservices scope matching the Azure OpenAI endpoint.
    """
    endpoint = os.environ.get("FOUNDRY_PROJECT_ENDPOINT", "")
    model = _resolve_model_deployment_name(model_override)
    api_version = os.environ.get("AZURE_OPENAI_API_VERSION", "2024-10-21")
    if endpoint and not model:
        raise RuntimeError(
            "FOUNDRY_PROJECT_ENDPOINT is set, but no valid model deployment name was found. "
            "Set AZURE_AI_MODEL_DEPLOYMENT_NAME (or MODEL_DEPLOYMENT_NAME / FOUNDRY_MODEL_DEPLOYMENT). "
            "Detected unresolved template values like ${...}."
        )
    if not endpoint or not model:
        return None, None

    base_url = _strip_project_path(endpoint)
    logger.info("BYOK provider base_url=%s model=%s", base_url, model)

    token = DefaultAzureCredential().get_token(
        "https://cognitiveservices.azure.com/.default"
    ).token

    if _wire_api(model) == "responses":
        # gpt-6 models reject function tools on chat completions; the v1 Responses API accepts them.
        provider = ProviderConfig(
            type="azure",
            base_url=f"{base_url}/openai/v1",
            wire_api="responses",
            bearer_token=token,
        )
        return provider, model

    provider = ProviderConfig(
        type="azure",
        base_url=f"{base_url}/openai/deployments/{model}",
        wire_api="completions",
        bearer_token=token,
        azure={"api_version": api_version},
    )
    return provider, model


def _wire_api(model: str) -> str:
    """`completions` or `responses`: AZURE_OPENAI_WIRE_API overrides; gpt-6 deployments default to `responses`."""
    forced = os.environ.get("AZURE_OPENAI_WIRE_API", "").strip().lower()
    if forced in {"completions", "responses"}:
        return forced
    return "responses" if "gpt-6" in model.lower() else "completions"


# ── Session management ───────────────────────────────────────────────────────


async def _ensure_session():
    """Resume a persisted session or create a new one (lazy, runs once)."""
    global _client, _session, _session_id, _toolbox_bridge, _tool_definitions
    if _session is not None:
        return

    _session_id = os.environ.get("FOUNDRY_AGENT_SESSION_ID")
    if not _session_id:
        _session_id = str(uuid.uuid4())
        logger.warning(
            "FOUNDRY_AGENT_SESSION_ID not set, using: %s", _session_id)

    optimization_config = _load_optimization_config()
    optimization_model = optimization_config.model if optimization_config else None
    optimization_instructions = (
        optimization_config.compose_instructions() if optimization_config else None
    )

    github_token = os.environ.get("GITHUB_TOKEN")
    provider, model = _byok_provider(optimization_model)

    if provider:
        # BYOK mode: Foundry model via Managed Identity — no token needed.
        _client = CopilotClient()
    elif github_token:
        # Copilot mode: use GitHub token.
        _client = CopilotClient(github_token=github_token)
    else:
        raise RuntimeError(
            "Set GITHUB_TOKEN (Copilot model) or "
            "FOUNDRY_PROJECT_ENDPOINT + AZURE_AI_MODEL_DEPLOYMENT_NAME "
            "(BYOK Foundry model)"
        )
    await _client.start()

    toolbox_url = _build_toolbox_mcp_url()
    if not toolbox_url:
        raise RuntimeError(
            "Toolbox configuration is required. Set FOUNDRY_PROJECT_ENDPOINT, TOOLBOX_NAME, and TOOLBOX_VERSION."
        )

    toolbox_tools: list[Tool] = []
    toolbox_skill_count = 0
    try:
        toolbox_token = DefaultAzureCredential().get_token(_AZURE_AI_SCOPE).token
        _toolbox_bridge = McpBridge(toolbox_url, toolbox_token)
        server_name = await _toolbox_bridge.initialize()
        # Skill-only toolboxes (definition "tools": []) reject tools/list, which the
        # platform records as a server error on every session start.
        mcp_tools = await _toolbox_bridge.list_tools() if _env_flag("TOOLBOX_DISCOVER_TOOLS", True) else []
        optimized_tools = _optimization_tool_definitions(optimization_config)
        toolbox_tools = _make_copilot_tools(_toolbox_bridge, mcp_tools, optimized_tools)
        toolbox_skill_count = await _sync_toolbox_skills(_toolbox_bridge, _toolbox_skills_dir)
        toolbox_tools.extend(_make_skill_backed_tools(
            optimized_tools, _toolbox_skills_dir, {tool.name for tool in toolbox_tools}
        ))
        logger.info(
            "Connected to toolbox MCP server '%s' with %d tools and %d synced skill resources",
            server_name,
            len(toolbox_tools),
            toolbox_skill_count,
        )
        if toolbox_skill_count == 0:
            raise RuntimeError(
                "Toolbox did not return any skill resources. "
                "Verify toolbox contents and access for TOOLBOX_NAME/TOOLBOX_VERSION."
            )
    except Exception as exc:
        logger.warning("Failed to initialize toolbox bridge: %s", exc)
        if _toolbox_bridge is not None:
            await _toolbox_bridge.close()
            _toolbox_bridge = None
        raise RuntimeError(
            "Toolbox skills are required but unavailable. "
            "Verify toolbox endpoint, identity access, TOOLBOX_NAME, and TOOLBOX_VERSION."
        ) from exc

    _tool_definitions = [
        {"name": tool.name, "description": tool.description,
         "parameters": tool.parameters or {"type": "object", "properties": {}}}
        for tool in toolbox_tools
    ]

    working_dir = os.environ.get("HOME", "/home")
    skill_directories = [_skills_dir]
    skill_backed_tool_names = {
        _skill_name_for_tool(definition["name"]) for definition in _tool_definitions
    }
    # Skills already exposed as function tools stay out of the native skill route,
    # so routing is observable through one tool contract.
    if toolbox_skill_count > 0 and any(
        path.is_dir() and path.name not in skill_backed_tool_names
        for path in pathlib.Path(_toolbox_skills_dir).iterdir()
    ):
        skill_directories.append(_toolbox_skills_dir)
    disabled_skills = sorted(skill_backed_tool_names) or None

    common = dict(
        on_permission_request=PermissionHandler.approve_all,
        streaming=True,
        skill_directories=skill_directories,
        disabled_skills=disabled_skills,
        # CLI bookkeeping tool; not part of the agent tool contract.
        excluded_tools=["report_intent"],
        working_directory=working_dir,
        provider=provider,
        model=model,
        tools=toolbox_tools,
        system_message=(
            {
                "mode": "customize",
                "sections": {
                    "identity": {"action": "replace", "content": optimization_instructions},
                    "code_change_rules": {"action": "remove"},
                },
            }
            if optimization_instructions
            else None
        ),
    )

    if optimization_config and optimization_instructions:
        logger.info(
            "Optimization config source=%s | model=%s | prompt_len=%d | skills=%d",
            optimization_config.source,
            model or optimization_model,
            len(optimization_instructions),
            len(optimization_config.skills),
        )

    try:
        _session = await _client.create_session(session_id=_session_id, **common)
        logger.info("Created session: %s", _session_id)
    except Exception as exc:
        if _session_already_exists_error(exc):
            _session = await _client.resume_session(_session_id, **common)
            logger.info("Resumed session: %s", _session_id)
        else:
            raise


def _text_from_event_data(data: Any, *fields: str) -> str:
    for field in fields:
        value = getattr(data, field, None)
        if isinstance(value, str) and value:
            return value
    return ""


def _jsonable(value: Any) -> Any:
    if value is None or isinstance(value, (str, int, float, bool)):
        return value
    if isinstance(value, dict):
        return {str(key): _jsonable(item) for key, item in value.items()}
    if isinstance(value, (list, tuple)):
        return [_jsonable(item) for item in value]
    to_dict = getattr(value, "to_dict", None)
    if callable(to_dict):
        return _jsonable(to_dict())
    return str(value)


_TOOL_RESULT_LIMIT = 8000


def _tool_call_record(data: Any) -> dict[str, Any]:
    arguments = _jsonable(getattr(data, "arguments", None))
    if isinstance(arguments, str):
        try:
            arguments = json.loads(arguments)
        except json.JSONDecodeError:
            pass
    return {
        "tool_call_id": getattr(data, "tool_call_id", None),
        "name": getattr(data, "tool_name", None),
        "arguments": arguments if arguments is not None else {},
    }


def _tool_result_record(data: Any) -> dict[str, Any]:
    result = getattr(data, "result", None)
    text = getattr(result, "content", None) if result is not None else None
    error = getattr(data, "error", None)
    record = {
        "tool_call_id": getattr(data, "tool_call_id", None),
        "success": bool(getattr(data, "success", False)),
        "result": text[:_TOOL_RESULT_LIMIT] if isinstance(text, str) else "",
    }
    if error is not None:
        record["error"] = getattr(error, "message", None) or str(error)
    return record


async def _copilot_stream_events(input_text: str, cancellation_signal: asyncio.Event):
    """Yield ("delta", text), ("tool_call", record) and ("tool_result", record) items."""
    await _ensure_session()
    queue: asyncio.Queue = asyncio.Queue()

    def on_event(event):
        if cancellation_signal.is_set():
            return
        if event.type == SessionEventType.SESSION_IDLE:
            queue.put_nowait(None)
        elif event.type == SessionEventType.SESSION_ERROR:
            queue.put_nowait(RuntimeError(
                getattr(event.data, "message", "error")))
        elif event.type == SessionEventType.MODEL_CALL_FAILURE:
            queue.put_nowait(RuntimeError(
                getattr(event.data, "error_message", "model call failed")))
        else:
            queue.put_nowait(event)

    unsubscribe = _session.on(on_event)
    emitted_delta = False
    final_message = ""
    try:
        await _session.send(input_text)
        while True:
            if cancellation_signal.is_set():
                break
            item = await queue.get()
            if item is None:
                break
            if isinstance(item, Exception):
                raise item

            if item.type == SessionEventType.ASSISTANT_MESSAGE_DELTA:
                chunk = _text_from_event_data(item.data, "delta_content")
                if chunk:
                    emitted_delta = True
                    yield "delta", chunk
            elif item.type == SessionEventType.ASSISTANT_MESSAGE:
                final_message = _text_from_event_data(item.data, "content")
            elif item.type == SessionEventType.TOOL_EXECUTION_START:
                yield "tool_call", _tool_call_record(item.data)
            elif item.type == SessionEventType.TOOL_EXECUTION_COMPLETE:
                yield "tool_result", _tool_result_record(item.data)
            elif item.type == SessionEventType.ASSISTANT_USAGE:
                yield "usage", item.data

        if final_message and not emitted_delta:
            yield "delta", final_message
    finally:
        unsubscribe()


def _extract_invocation_input(payload: Any) -> str:
    if isinstance(payload, str):
        return payload.strip()
    if not isinstance(payload, dict):
        return ""

    for key in ("input", "message", "prompt", "query"):
        value = payload.get(key)
        if isinstance(value, str) and value.strip():
            return value.strip()
    return ""


def _content_safety_incidents() -> list[str]:
    raw = (
        os.environ.get("AZURE_CONTENT_SAFETY_INCIDENTS")
        or os.environ.get("AZURE_CONTENT_SAFETY_INCIDENT")
        or ""
    ).strip()
    if not raw:
        return []
    if raw.startswith("["):
        value = json.loads(raw)
        if not isinstance(value, list) or any(not isinstance(item, str) or not item.strip() for item in value):
            raise ValueError("AZURE_CONTENT_SAFETY_INCIDENTS must be a JSON string array or comma-separated names")
        incidents = [item.strip() for item in value]
    else:
        incidents = [item.strip() for item in raw.split(",") if item.strip()]
    return list(dict.fromkeys(incidents))


def _activated_content_safety_incidents(input_text: str) -> list[str]:
    incidents = _content_safety_incidents()
    raw = (os.environ.get("AZURE_CONTENT_SAFETY_ACTIVATION_RULES") or "").strip()
    if not raw:
        return incidents
    value = json.loads(raw)
    if not isinstance(value, list):
        raise ValueError("AZURE_CONTENT_SAFETY_ACTIVATION_RULES must be a JSON array")
    rules: dict[str, list[str]] = {}
    for item in value:
        if not isinstance(item, dict) or not isinstance(item.get("name"), str):
            raise ValueError("each Content Safety activation rule must have a name")
        terms = item.get("activation_terms")
        if not isinstance(terms, list) or not terms or any(not isinstance(term, str) or not term for term in terms):
            raise ValueError("each Content Safety activation rule must have non-empty activation_terms")
        rules[item["name"]] = terms
    if set(rules) != set(incidents):
        raise ValueError("Content Safety activation rules must cover every configured incident")
    folded = input_text.casefold()
    return [
        incident
        for incident in incidents
        if any(term.casefold() in folded for term in rules[incident])
    ]


async def _custom_content_safety_matches(input_text: str) -> list[str]:
    endpoint = (os.environ.get("AZURE_CONTENT_SAFETY_ENDPOINT") or "").rstrip("/")
    incidents = _activated_content_safety_incidents(input_text)
    if not endpoint or not incidents:
        return []

    token = await asyncio.to_thread(
        DefaultAzureCredential().get_token,
        "https://cognitiveservices.azure.com/.default",
    )
    async with httpx.AsyncClient(timeout=30) as client:
        response = await client.post(
            f"{endpoint}/contentsafety/text:detectIncidents",
            params={"api-version": "2024-02-15-preview"},
            headers={"Authorization": "Bearer " + token.token},
            json={"text": input_text, "incidentNames": incidents},
        )
    response.raise_for_status()
    payload = response.json()
    return [
        match["incidentName"]
        for match in payload.get("incidentMatches", [])
        if isinstance(match, dict) and isinstance(match.get("incidentName"), str)
    ]


def _custom_category_refusal(matches: list[str]) -> str:
    logger.warning("Content Safety custom category matched: %s", matches)
    return "I can't help with this request because it matches a configured Content Safety policy."


def _content_safety_unavailable() -> str:
    return (
        "I can't process this request because the Content Safety check is temporarily unavailable. "
        "Please try again later."
    )


@app.response_handler
async def handle_response(request, context, cancellation_signal):
    input_text = await context.get_input_text()
    if not input_text:
        raise ValueError('Request body must contain a non-empty "input" value.')
    try:
        matches = await _custom_content_safety_matches(input_text)
    except (httpx.HTTPError, ValueError) as exc:
        logger.error("Content Safety custom-category check failed: %s", exc)

        async def unavailable_stream():
            yield _content_safety_unavailable()

        return TextResponse(context, request, text=unavailable_stream())
    if matches:
        async def blocked_stream():
            yield _custom_category_refusal(matches)

        return TextResponse(context, request, text=blocked_stream())

    conversation_id = str(getattr(context, "conversation_id", None) or getattr(context, "response_id", None) or uuid.uuid4())
    memory = _agent_memory()
    turn = await memory.begin(None, input_text)
    model_input = memory.compose(turn, input_text, conversation_id)

    async def text_stream():
        # Foundry evaluations, trace evaluation and continuous evaluation all call the Responses protocol, and they read
        # the conversation from the invocation span's gen_ai.input/output.messages. Without this span the traces carry
        # no message content and every continuous-evaluation run is "skipped" (AgentOps Doctor then blocks the release).
        chunks: list[str] = []
        calls: list[dict[str, Any]] = []
        results: dict[str, dict[str, Any]] = {}
        with _start_invocation_span(conversation_id) as span:
            span.set_attribute("input.value_length", len(input_text))
            _set_memory_span_attributes(span, turn)
            try:
                async for kind, value in _copilot_stream_events(model_input, cancellation_signal):
                    if kind == "delta":
                        chunks.append(value)
                        yield value
                    elif kind == "usage":
                        _record_model_call(value)
                    elif kind == "tool_call":
                        calls.append(value)
                    elif kind == "tool_result":
                        results[value.get("tool_call_id")] = value
                assistant_text = "".join(chunks)
                await memory.remember(turn, input_text, assistant_text)
                _set_memory_span_attributes(span, turn)
                _finish_invocation_span(span, input_text, assistant_text, calls, results)
            except Exception as exc:
                _mark_span_error(span, exc)
                raise
        _force_flush_tracing()

    return TextResponse(context, request, text=text_stream())


def _extract_invocation_session_id(request: Request, payload: Any) -> str:
    if isinstance(payload, dict):
        for key in ("conversation_id", "conversationId", "session_id", "sessionId"):
            value = payload.get(key)
            if isinstance(value, str) and value.strip():
                return value.strip()

    state = getattr(request, "state", None)
    for key in ("conversation_id", "session_id", "agent_session_id"):
        value = getattr(state, key, None)
        if isinstance(value, str) and value.strip():
            return value.strip()

    return _session_id or str(uuid.uuid4())


def _content_recording_enabled() -> bool:
    return _env_flag("AZURE_TRACING_GEN_AI_CONTENT_RECORDING_ENABLED")


def _start_invocation_span(conversation_id: str):
    if _tracer is None:
        return nullcontext(_NoopSpan())

    return _tracer.start_as_current_span(
        f"invoke_agent {_agent_id()}",
        kind=SpanKind.SERVER if SpanKind is not None else None,
        attributes={
            "gen_ai.operation.name": "chat",
            "gen_ai.system": "github_copilot_sdk",
            "gen_ai.agent.name": _agent_name(),
            "gen_ai.agent.id": _agent_id(),
            "gen_ai.conversation.id": conversation_id,
            "azure.ai.agentserver.agent_name": _agent_name(),
            "azure.ai.agentserver.agent_id": _agent_id(),
            "azure.ai.agentserver.conversation_id": conversation_id,
            "server.address": "hosted-agent-github-copilot",
        },
    )


def _set_memory_span_attributes(span, turn: agent_memory.Turn) -> None:
    span.set_attribute("f100.memory.active", turn.active)
    span.set_attribute("f100.memory.recalled_count", len(turn.memories))
    span.set_attribute("f100.memory.stored", turn.stored)
    span.set_attribute("f100.memory.reason", turn.reason or "none")


def _genai_messages(input_text: str, assistant_text: str, tool_calls: list[dict[str, Any]],
                    tool_results: dict[str, dict[str, Any]]) -> tuple[str, str]:
    """OpenTelemetry GenAI `gen_ai.input.messages` / `gen_ai.output.messages` JSON values.

    Foundry trace evaluation reads these (not the legacy gen_ai.prompt/completion).
    """
    inputs = [{"role": "user", "parts": [{"type": "text", "content": input_text}]}]
    outputs = []
    for call in tool_calls:
        outputs.append({"role": "assistant", "parts": [{
            "type": "tool_call", "id": call.get("tool_call_id"), "name": call.get("name"),
            "arguments": call.get("arguments")}]})
        result = tool_results.get(call.get("tool_call_id"))
        if result is not None:
            outputs.append({"role": "tool", "parts": [{
                "type": "tool_call_response", "id": call.get("tool_call_id"),
                "response": result.get("result") if result.get("success") else f"ERROR: {result.get('error')}"}]})
    outputs.append({"role": "assistant", "parts": [{"type": "text", "content": assistant_text}],
                    "finish_reason": "stop"})
    return json.dumps(inputs), json.dumps(outputs)


def _finish_invocation_span(span, input_text: str, assistant_text: str,
                            tool_calls: list[dict[str, Any]] | None = None,
                            tool_results: dict[str, dict[str, Any]] | None = None):
    span.set_attribute("gen_ai.response.finish_reasons", json.dumps(["stop"]))
    span.set_attribute("output.value_length", len(assistant_text))
    if _content_recording_enabled():
        input_messages, output_messages = _genai_messages(
            input_text, assistant_text, tool_calls or [], tool_results or {})
        span.set_attribute("gen_ai.input.messages", input_messages)
        span.set_attribute("gen_ai.output.messages", output_messages)
        span.set_attribute("gen_ai.completion", assistant_text)
        span.add_event(
            "gen_ai.assistant.message",
            {"content": assistant_text, "role": "assistant"},
        )


def _record_model_call(data: Any) -> None:
    """Emit an OpenTelemetry GenAI client span for one model call reported by the Copilot SDK.

    The SDK calls the model inside its CLI process, so no client span exists otherwise;
    token usage then never reaches Application Insights `dependencies`.
    """
    if _tracer is None:
        return
    model = getattr(data, "model", None) or _resolve_model_deployment_name() or "unknown"
    duration = getattr(data, "duration", None)
    seconds = duration.total_seconds() if hasattr(duration, "total_seconds") else 0
    end_ns = time.time_ns()
    start_ns = end_ns - int(seconds * 1_000_000_000) if seconds > 0 else end_ns
    attributes = {"gen_ai.operation.name": "chat", "gen_ai.system": "az.ai.openai",
                  "gen_ai.request.model": model, "gen_ai.response.model": model,
                  "server.address": "hosted-agent-github-copilot"}
    for source, target in (("input_tokens", "gen_ai.usage.input_tokens"),
                           ("output_tokens", "gen_ai.usage.output_tokens")):
        value = getattr(data, source, None)
        if isinstance(value, (int, float)):
            attributes[target] = int(value)
    span = _tracer.start_span(f"chat {model}", kind=SpanKind.CLIENT if SpanKind is not None else None,
                              attributes=attributes, start_time=start_ns)
    span.end(end_time=end_ns)


def _mark_span_error(span, exc: Exception):
    span.record_exception(exc)
    if Status is not None and StatusCode is not None:
        span.set_status(Status(StatusCode.ERROR, str(exc)))


def _force_flush_tracing():
    if trace is None:
        return
    provider = trace.get_tracer_provider()
    force_flush = getattr(provider, "force_flush", None)
    if callable(force_flush):
        try:
            force_flush(timeout_millis=5000)
        except Exception as exc:
            logger.debug("Tracing force_flush failed: %s", exc)


def _tool_events_requested(payload: Any) -> bool:
    return isinstance(payload, dict) and payload.get("include_tool_events") is True


def _sse(payload: dict[str, Any]) -> bytes:
    return f"data: {json.dumps(payload)}\n\n".encode()


@app.invoke_handler
async def handle_invoke(request: Request) -> Response:
    body = await request.body()
    if not body:
        return JSONResponse(
            {
                "error": "Request body is required. For azd invocations, pass a JSON payload with --input-file, for example {\"input\": \"Hello\"}.",
            },
            status_code=400,
        )

    try:
        payload = json.loads(body)
    except json.JSONDecodeError:
        payload = body.decode("utf-8", errors="replace")

    input_text = _extract_invocation_input(payload)
    if not input_text:
        return JSONResponse(
            {"error": 'Request body must contain a non-empty "input" value.'},
            status_code=400,
        )

    cancellation_signal = asyncio.Event()
    conversation_id = _extract_invocation_session_id(request, payload)
    include_tool_events = _tool_events_requested(payload)
    try:
        matches = await _custom_content_safety_matches(input_text)
    except (httpx.HTTPError, ValueError) as exc:
        logger.error("Content Safety custom-category check failed: %s", exc)
        return JSONResponse(
            {"error": "Content Safety custom-category check failed; the request was not processed."},
            status_code=503,
        )
    if matches:
        async def blocked():
            yield _sse({"delta": _custom_category_refusal(matches)})
            if include_tool_events:
                yield _sse({"type": "content_safety", "custom_categories": matches})
            yield b"event: done\ndata: {}\n\n"

        return StreamingResponse(
            blocked(),
            media_type="text/event-stream",
            headers={"Cache-Control": "no-cache"},
        )

    memory = _agent_memory()
    turn = await memory.begin(payload, input_text, request.headers)
    model_input = memory.compose(turn, input_text, conversation_id)

    async def generate():
        assistant_chunks: list[str] = []
        observed_calls: list[dict[str, Any]] = []
        observed_results: dict[str, dict[str, Any]] = {}
        error_frame: bytes | None = None
        with _start_invocation_span(conversation_id) as span:
            span.set_attribute("input.value_length", len(input_text))
            _set_memory_span_attributes(span, turn)
            if _content_recording_enabled():
                span.set_attribute("gen_ai.prompt", input_text)
                span.add_event(
                    "gen_ai.user.message",
                    {"content": input_text, "role": "user"},
                )

            try:
                tool_definitions_sent = False
                async for kind, value in _copilot_stream_events(model_input, cancellation_signal):
                    if include_tool_events and not tool_definitions_sent:
                        tool_definitions_sent = True
                        yield _sse({"type": "tool_definitions", "tools": _tool_definitions})
                    if kind == "delta":
                        assistant_chunks.append(value)
                        yield _sse({"type": "token", "delta": value})
                        continue
                    if kind == "usage":
                        _record_model_call(value)
                        continue
                    if kind == "tool_call":
                        observed_calls.append(value)
                    elif kind == "tool_result":
                        observed_results[value.get("tool_call_id")] = value
                    span.add_event(f"gen_ai.{kind}", {
                        "gen_ai.tool.call.id": value.get("tool_call_id") or "",
                        **({"gen_ai.tool.name": value["name"]} if value.get("name") else {}),
                    })
                    if include_tool_events:
                        yield _sse({"type": kind, **value})
                if include_tool_events and not tool_definitions_sent:
                    yield _sse({"type": "tool_definitions", "tools": _tool_definitions})
                assistant_text = "".join(assistant_chunks)
                await memory.remember(turn, input_text, assistant_text)
                _set_memory_span_attributes(span, turn)
                _finish_invocation_span(span, input_text, assistant_text, observed_calls, observed_results)
            except Exception as exc:
                _mark_span_error(span, exc)
                error_frame = _sse({"type": "error", "message": str(exc)})
            finally:
                cancellation_signal.set()
        # The span has ended. Export telemetry before signalling completion: callers often
        # delete the session (and its container) as soon as they receive `done`.
        _force_flush_tracing()
        if include_tool_events:
            yield _sse(turn.event())
        if error_frame is not None:
            yield error_frame
        yield b"event: done\ndata: {}\n\n"

    return StreamingResponse(
        generate(),
        media_type="text/event-stream",
        headers={"Cache-Control": "no-cache"},
    )


if __name__ == "__main__":
    has_token = bool(os.environ.get("GITHUB_TOKEN"))
    has_project_endpoint = bool(os.environ.get("FOUNDRY_PROJECT_ENDPOINT"))
    has_valid_model_name = bool(_resolve_model_deployment_name())
    has_byok = bool(has_project_endpoint and has_valid_model_name)

    if has_project_endpoint and not has_valid_model_name and not has_token:
        import sys
        sys.exit(
            "Error: FOUNDRY_PROJECT_ENDPOINT is set but no valid model deployment name was found. "
            "Set AZURE_AI_MODEL_DEPLOYMENT_NAME (or MODEL_DEPLOYMENT_NAME / FOUNDRY_MODEL_DEPLOYMENT). "
            "Do not leave unresolved template values like ${AZURE_AI_MODEL_DEPLOYMENT_NAME}."
        )

    if not has_token and not has_byok:
        import sys
        sys.exit(
            "Error: Set GITHUB_TOKEN (Copilot model) or "
            "FOUNDRY_PROJECT_ENDPOINT + AZURE_AI_MODEL_DEPLOYMENT_NAME "
            "(BYOK Foundry model)"
        )
    app.run()
